    // ---------- 档案变更使已发布占用越限 → 409 ----------

    @Test
    void profileChangeBreakingPublishedOccupancyRejected() throws Exception {
        String trainNo = key("TRN");
        String section = key("SEC");
        createTrainProfile(trainNo, "1", "2");
        createSectionProfile(section, "35");
